'use strict';

/**
* Factorize a sequence length into a product of integers and store the results in an unsigned integer array.
*
* @module @stdlib/fft/base/fftpack/float32/decompose
*
* @example
* var Uint32Array = require( '@stdlib/array/uint32' );
* var decompose = require( '@stdlib/fft/base/fftpack/float32/decompose' );
*
* var N = 630;
* var initial = new Uint32Array( [ 3, 4, 2, 5 ] ); // as found in FFTPACK
* var factors = new Uint32Array( 7 );
*
* var numFactors = decompose( N, 4, initial, 1, 0, factors, 1, 0 );
* // returns 5
*
* @example
* var Uint32Array = require( '@stdlib/array/uint32' );
* var decompose = require( '@stdlib/fft/base/fftpack/float32/decompose' );
*
* var N = 12;
* var initial = new Uint32Array( [ 3, 4, 2, 5 ] ); // as found in FFTPACK
* var factors = new Uint32Array( 4 );
*
* var numFactors = decompose( N, 4, initial, 1, 0, factors, 1, 0 );
* // returns 2
*/

// MODULES //

var main = require( './main.js' );


// EXPORTS //

module.exports = main;
